def semver_sort(versions):
    def parse_version(version):
        # Split version and build metadata
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version
            build = ''

        # Split version core and pre-release
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            prerelease_identifiers = []
            for identifier in identifiers:
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_key(version):
        major, minor, patch, prerelease_identifiers = parse_version(version)

        # If no pre-release, it sorts after with pre-release
        if prerelease_identifiers is None:
            # Use a tuple that sorts after any pre-release version
            return (major, minor, patch, (1,))
        else:
            # Pre-release versions sort before release versions
            return (major, minor, patch, (0, tuple(prerelease_identifiers)))

    # Sort with stable sort to preserve input order for equal versions
    return sorted(versions, key=compare_key)

